    shortcut: "ترتیب پدر و فرزند حفظ می‌شود، ولی اگر دو زیردرخت هم‌اندازه نباشند درخت دیگر کامل نیست؛ پس «در برخی شرایط»؛ گزینهٔ ۳.",
