  "kunkurcomputer-q-1209-1389-3077-061": {
    answer: 1,
    hint: "زمان متوسط جست‌وجو در هر ساختار را بنویس: کدام به N بستگی ندارد؟",
    shortcut: String.raw`جدول درهم‌سازی با ضریب بار ثابت (اینجا $N$ عنصر در $N$ خانه) جست‌وجوی متوسط $O(1)$ دارد؛ آرایهٔ مرتب $O(\log N)$ و لیست‌های پیوندی $O(N)$؛ گزینهٔ ۱.`,
    solution: [
      t(String.raw`لیست درهم‌سازی به طول $N$ برای $N$ عنصر یعنی ضریب بار $\alpha=1$؛ با فرض درهم‌سازی یکنواخت، جست‌وجوی موفق به‌طور متوسط $1+\frac\alpha2=O(1)$ مقایسه دارد.`),
      t(String.raw`آرایهٔ مرتب با جست‌وجوی دودویی $O(\log N)$ است. لیست پیوندی مرتب، چه یک‌طرفه چه دوطرفه، دسترسی تصادفی ندارد و جست‌وجوی دودویی رویش کارا نیست؛ باید از ابتدا پیمود: به‌طور متوسط $\frac N2$ گره، یعنی $O(N)$.`),
      t(String.raw`سریع‌ترین در حالت متوسط: درهم‌سازی؛ گزینهٔ ۱.`),
    ],
  },
  "kunkurcomputer-q-1209-1389-3077-091": {
    answer: 2,
    hint: "از گوشهٔ بالا-راست شروع کن. با هر مقایسه چه چیزی حذف می‌شود؟",
    shortcut: String.raw`از گوشهٔ بالا-راست: اگر عنصر از $z$ بزرگ‌تر بود یک ستون چپ برو (کل آن ستون حذف)، اگر کوچک‌تر بود یک سطر پایین برو (کل آن سطر حذف). حداکثر $2n-1$ گام: $O(n)$؛ گزینهٔ ۲.`,
    solution: [
      t(String.raw`از خانهٔ $(1,n)$ شروع می‌کنیم. اگر $a=z$ پیدا شد. اگر $a>z$، همهٔ عناصر زیر $a$ در همین ستون از $a$ بزرگ‌ترند، پس کل ستون کنار می‌رود و یک ستون به چپ می‌رویم. اگر $a<z$، همهٔ عناصر چپ $a$ در این سطر کوچک‌ترند، پس کل سطر کنار می‌رود و یک سطر پایین می‌رویم.`),
      t(String.raw`هر گام یک سطر یا یک ستون حذف می‌کند، پس حداکثر $2n-1$ مقایسه: $O(n)$.`),
      t(String.raw`این بهینه هم هست: عناصر قطر فرعی ($a_{i,n+1-i}$) با هم ترتیب مشخصی ندارند و $z$ ممکن است هر کدام از آن‌ها باشد، پس $\Omega(n)$ مقایسه لازم است. جست‌وجوی دودویی در هر سطر $O(n\log n)$ می‌دهد (گزینهٔ ۴)، و تقسیم ماتریس به چهار بخش $O(n^{\log_23})$ (گزینهٔ ۳). جواب: گزینهٔ ۲.`),
    ],
  },
  "kunkurcomputer-q-1209-1389-3077-093": {
    answer: 3,
    hint: "هر پرسش بله یا خیر است؛ بهترین کار این است که هر بار نیمی از نامزدها را بپرسی.",
    shortcut: String.raw`نیمی از نامزدها را بپرس: جواب «بله» یا «خیر» هر بار نامزدها را نصف می‌کند؛ $\lceil\log_2n\rceil$ پرسش. با $q$ پرسش بله/خیر حداکثر $2^q$ حالت تشخیص داده می‌شود، پس کمتر هم ممکن نیست؛ گزینهٔ ۳.`,
    solution: [
      t(String.raw`راهبرد: نامزدها را دو نیمه کن و از یک نیمه بپرس. اگر «بله»، نابغه در آن نیمه است، وگرنه در نیمهٔ دیگر. این همان جست‌وجوی دودویی است و $\lceil\log_2n\rceil$ پرسش کافی است.`),
      t(String.raw`کران پایین: هر پرسش دو جواب ممکن دارد، پس $q$ پرسش حداکثر $2^q$ دنبالهٔ جواب متفاوت می‌سازد. برای تشخیص یکی از $n$ نفر باید $2^q\ge n$، یعنی $q\ge\log_2n$.`),
      t(String.raw`پیچیدگی بهترین راه‌حل $\Theta(\log n)$ است؛ گزینهٔ ۳.`),
    ],
  },
  "kunkurcomputer-q-1209-1391-368C-062": {
    answer: 2,
    hint: String.raw`نقطهٔ $\frac13$ یعنی $l$ به‌اضافهٔ یک‌سوم طول بازه.`,
    shortcut: String.raw`$m_1=l+\frac{h-l}3=\frac{2l+h}3$ و $m_2=l+\frac{2(h-l)}3=\frac{l+2h}3$؛ گزینهٔ ۲.`,
    solution: [
      t(String.raw`طول بازه $h-l$ است. نقطهٔ یک‌سوم: $m_1=l+\frac{h-l}3=\frac{3l+h-l}3=\frac{h+2l}3$. نقطهٔ دوسوم: $m_2=l+\frac{2(h-l)}3=\frac{2h+l}3$.`),
      t(String.raw`راه وارسی: با $l=0$ و $h=9$ باید $m_1=3$ و $m_2=6$ شود. گزینهٔ ۲ همین را می‌دهد؛ در گزینهٔ ۱، $m_2=3$ و در گزینه‌های ۳ و ۴ برای $l\neq0$ نقطه‌ها حتی ممکن است بیرون بازه بیفتند (مثلاً $l=9,h=12$ در گزینهٔ ۳ می‌دهد $m_1=7$).`),
    ],
  },
  "kunkurcomputer-q-1209-1391-368C-089": {
    answer: 2,
    hint: "عنصر وسط را با آخرین عنصر مقایسه کن: کمینه در کدام نیمه است؟",
    shortcut: String.raw`اگر $x_{mid}>x_{h}$، چرخش (و کمینه) در نیمهٔ راست است؛ وگرنه کمینه در نیمهٔ چپ (با خود mid). هر بار بازه نصف می‌شود: $O(\log n)$؛ گزینهٔ ۲.`,
    solution: [
      t(String.raw`دنبالهٔ چرخشی دو بخش صعودی دارد که بخش اول همه از بخش دوم بزرگ‌ترند و کمینه اول بخش دوم است. اگر $x_{mid}>x_h$، $mid$ در بخش اول است و کمینه در $(mid,h]$؛ اگر $x_{mid}<x_h$، $mid$ در بخش دوم است و کمینه در $[l,mid]$.`),
      t(String.raw`هر مقایسه بازه را نصف می‌کند: $T(n)=T(\frac n2)+O(1)=O(\log n)$؛ گزینهٔ ۲. (فرض این است که عناصر متمایزند؛ با عناصر تکراری بدترین حالت به $O(n)$ می‌رسد.)`),
    ],
  },
  "kunkurcomputer-q-1209-1391-368C-090": {
    answer: 1,
    hint: "الگوریتم رأی اکثریت بویر–مور را برای دو نامزد تعمیم بده.",
    shortcut: String.raw`حداکثر دو عنصر می‌توانند بیش از $\frac n3$ بار بیایند. با دو نامزد و دو شمارنده (تعمیم بویر–مور) در یک پیمایش نامزدها را پیدا کن و در پیمایش دوم بشمار: $O(n)$ زمان و $O(1)$ حافظه؛ گزینهٔ ۱.`,
    solution: [
      t(String.raw`دو نامزد $c_1,c_2$ و شمارنده‌های $k_1,k_2$ نگه می‌داریم. برای هر عنصر $x$: اگر برابر یکی از نامزدهاست شمارنده‌اش را زیاد کن؛ وگرنه اگر شمارنده‌ای صفر است $x$ را نامزد آن کن؛ وگرنه هر دو شمارنده را یکی کم کن. هر «کم کردن» سه عنصر متفاوت را با هم حذف می‌کند، پس عنصری که بیش از $\frac n3$ بار آمده نمی‌تواند کاملاً حذف شود و آخر کار نامزد است.`),
      t(String.raw`در پیمایش دوم تعداد واقعی دو نامزد را می‌شماریم تا ببینیم کدام بیش از $\frac n3$ بار آمده. دو پیمایش: $O(n)$ زمان و چند متغیر: $O(1)$ حافظه.`),
      t(String.raw`مرتب‌سازی $O(n\log n)$ است (گزینهٔ ۴)؛ شمارش با جدول درهم‌سازی خطی است ولی حافظهٔ $O(n)$ می‌خواهد. جواب: گزینهٔ ۱.`),
    ],
  },
