    shortcut: String.raw`گره‌ها را با جابه‌جایی اشاره‌گرها یکی در میان به هم وصل کن؛ وقتی لیست کوتاه‌تر تمام شد، بقیهٔ لیست بلندتر از قبل به هم وصل است و فقط یک اشاره‌گر کافی است: $O(\min(m,n))$؛ گزینهٔ ۴.`,
