  "kunkurcomputer-q-1209-1389-3077-094": {
    answer: 4,
    hint: String.raw`با درهم‌سازی یکنواخت، احتمال خالی بودن هر خانهٔ کاوش‌شده $1-\alpha$ است.`,
    shortcut: String.raw`با آدرس‌دهی باز و درهم‌سازی یکنواخت، تعداد مورد انتظار کاوش در جست‌وجوی ناموفق حداکثر $\frac1{1-\alpha}=\frac1{0.25}=4$ است؛ گزینهٔ ۴.`,
    solution: [
      t(String.raw`در درهم‌سازی یکنواخت، دنبالهٔ کاوش هر کلید یک جایگشت تصادفی از خانه‌هاست. جست‌وجوی ناموفق تا اولین خانهٔ خالی ادامه می‌یابد. احتمال پر بودن کاوش اول $\alpha$، دو کاوش اول $\le\alpha^2$ و الی آخر.`),
      t(String.raw`امید تعداد کاوش‌ها: $\sum_{i\ge0}\alpha^i=\frac1{1-\alpha}$ (کران بالای تحلیل CLRS). با $\alpha=0.75$: $\frac1{0.25}=4$.`),
      t(String.raw`منظور از «حداکثر» در سؤال همین کران بالای امید است، نه بدترین حالت مطلق (که می‌تواند همهٔ خانه‌ها باشد). جواب: گزینهٔ ۴. برای جست‌وجوی موفق کران $\frac1\alpha\ln\frac1{1-\alpha}\approx1.85$ است.`),
    ],
  },
