    shortcut: "$\\bar x_1$ درست → $x_1=0$؛ $x_1\\lor\\bar x_2$ → $x_2=0$؛ و همین‌طور تا $x_n=0$. پس همه نادرست‌اند و $\\bar x_1\\land\\cdots\\land\\bar x_n$ درست است؛ گزینهٔ ۳.",
